import 'dart:io';

// UI sources are Flutter/Dart. Browser JavaScript is generated by Flutter.
Future<void> main() async {
  final artifact = File.fromUri(Platform.script).parent.parent;
  final example = Directory.fromUri(
    artifact.uri.resolve('../../packages/device_identity/example/'),
  );
  final output = Directory.fromUri(artifact.uri.resolve('dist/public/'));
  final base = Platform.environment['BASE_PATH'] ?? '/device-identity/';
  if (!base.startsWith('/') || !base.endsWith('/')) {
    stderr.writeln('BASE_PATH must start and end with /.');
    exit(1);
  }
  try {
    final process = await Process.start(
      'flutter',
      [
        'build', 'web', '--release',
        '--target=lib/main_preview.dart',
        '--no-web-resources-cdn',
        '--pwa-strategy=none',
        '--base-href=$base',
        '--output=${output.path}',
      ],
      workingDirectory: example.path,
      mode: ProcessStartMode.inheritStdio,
      runInShell: Platform.isWindows,
    );
    exit(await process.exitCode);
  } on ProcessException catch (error) {
    stderr.writeln('Flutter SDK is required to build the Dart preview: $error');
    exit(1);
  }
}
